import { useMemo, useState } from 'react';
import { JxButton } from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over' | 'archived';

type Project = {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
};

type ProjectSpendPanelProps = {
  projects?: Project[];
};

const STATUS_LABEL: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'На паузе',
  over: 'Превышение',
  archived: 'В архиве',
};

const STATUS_TONE: Record<ProjectStatus, string> = {
  active: 'success',
  paused: 'neutral',
  over: 'danger',
  archived: 'muted',
};

const STATUSES = Object.keys(STATUS_LABEL) as ProjectStatus[];

const PAGE_SIZE = 5;
const RING_RADIUS = 18;
const RING_LENGTH = 2 * Math.PI * RING_RADIUS;

const DEFAULT_PROJECTS: Project[] = [
  { id: 'atlas', name: 'Atlas Ingest', used: 8200, quota: 10000, status: 'active' },
  { id: 'beacon', name: 'Beacon Search', used: 11400, quota: 9000, status: 'over' },
  { id: 'cobalt', name: 'Cobalt Billing', used: 1500, quota: 6000, status: 'paused' },
  { id: 'delta', name: 'Delta Reports', used: 4300, quota: 5000, status: 'active' },
  { id: 'echo', name: 'Echo Notifications', used: 900, quota: 4000, status: 'paused' },
  { id: 'forge', name: 'Forge Pipelines', used: 7600, quota: 8000, status: 'active' },
  { id: 'gamma', name: 'Gamma Sandbox', used: 15200, quota: 12000, status: 'over' },
  { id: 'harbor', name: 'Harbor Storage', used: 2400, quota: 7000, status: 'active' },
];

export default function ProjectSpendPanel({ projects = DEFAULT_PROJECTS }: ProjectSpendPanelProps) {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(STATUSES);
  const [requestedPage, setRequestedPage] = useState(0);

  const visible = useMemo(
    () => projects.filter((project) => activeStatuses.includes(project.status)),
    [projects, activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(visible.length / PAGE_SIZE));
  const page = Math.min(requestedPage, pageCount - 1);
  const rows = visible.slice(page * PAGE_SIZE, page * PAGE_SIZE + PAGE_SIZE);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((current) =>
      current.includes(status) ? current.filter((item) => item !== status) : [...current, status],
    );
    setRequestedPage(0);
  };

  const resetFilters = () => {
    setActiveStatuses(STATUSES);
    setRequestedPage(0);
  };

  return (
    <section className="jx-card jx-stack" style={{ gap: 'var(--jx-space-5)' }}>
      <header className="jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
        <h2 className="jx-heading">Расход по проектам</h2>
        <p className="jx-text jx-text--muted">Заполненность квоты за текущий период</p>
      </header>

      <div
        className="jx-cluster"
        role="group"
        aria-label="Фильтр по статусу"
        style={{ gap: 'var(--jx-space-2)', flexWrap: 'wrap' }}
      >
        {STATUSES.map((status) => {
          const selected = activeStatuses.includes(status);
          return (
            <button
              key={status}
              type="button"
              className={`jx-chip${selected ? ' jx-chip--selected' : ''}`}
              aria-pressed={selected}
              onClick={() => toggleStatus(status)}
            >
              <span className="jx-chip__label">{STATUS_LABEL[status]}</span>
              {selected ? (
                <span className="jx-chip__remove" aria-hidden="true">
                  ×
                </span>
              ) : null}
            </button>
          );
        })}
      </div>

      {rows.length === 0 ? (
        <div className="jx-empty-state jx-stack" style={{ gap: 'var(--jx-space-3)' }}>
          <p className="jx-text">Под выбранные фильтры не подошёл ни один проект.</p>
          <JxButton variant="primary" onClick={resetFilters}>
            Сбросить фильтры
          </JxButton>
        </div>
      ) : (
        <ul className="jx-list" style={{ listStyle: 'none', margin: 0, padding: 0 }}>
          {rows.map((project) => {
            const percent = Math.round((project.used / project.quota) * 100);
            const filled = Math.min(100, Math.max(0, percent));
            const tone = STATUS_TONE[project.status];
            return (
              <li
                key={project.id}
                className="jx-list__item jx-cluster"
                style={{
                  gap: 'var(--jx-space-4)',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                }}
              >
                <span className="jx-text jx-text--strong">{project.name}</span>

                <span
                  className={`jx-cluster jx-tone--${tone}`}
                  style={{ gap: 'var(--jx-space-3)', alignItems: 'center' }}
                >
                  <svg
                    width={44}
                    height={44}
                    viewBox="0 0 44 44"
                    role="progressbar"
                    aria-valuemin={0}
                    aria-valuemax={100}
                    aria-valuenow={filled}
                    aria-label={`Квота проекта ${project.name}: ${percent}%`}
                  >
                    <circle
                      cx={22}
                      cy={22}
                      r={RING_RADIUS}
                      fill="none"
                      stroke="var(--jx-color-border)"
                      strokeWidth={4}
                    />
                    <circle
                      cx={22}
                      cy={22}
                      r={RING_RADIUS}
                      fill="none"
                      stroke="currentColor"
                      strokeWidth={4}
                      strokeLinecap="round"
                      strokeDasharray={RING_LENGTH}
                      strokeDashoffset={RING_LENGTH * (1 - filled / 100)}
                      transform="rotate(-90 22 22)"
                    />
                    <text
                      x={22}
                      y={22}
                      textAnchor="middle"
                      dominantBaseline="central"
                      fill="var(--jx-color-fg)"
                      fontSize="var(--jx-font-size-xs)"
                    >
                      {percent}%
                    </text>
                  </svg>

                  <span className={`jx-badge jx-badge--${tone}`}>{STATUS_LABEL[project.status]}</span>
                </span>
              </li>
            );
          })}
        </ul>
      )}

      {rows.length > 0 ? (
        <footer
          className="jx-cluster"
          style={{ gap: 'var(--jx-space-3)', alignItems: 'center', justifyContent: 'space-between' }}
        >
          <span className="jx-text jx-text--muted">
            Страница {page + 1} из {pageCount}
          </span>
          <span className="jx-cluster" style={{ gap: 'var(--jx-space-2)' }}>
            <JxButton
              variant="secondary"
              disabled={page === 0}
              onClick={() => setRequestedPage(page - 1)}
            >
              Назад
            </JxButton>
            <JxButton
              variant="secondary"
              disabled={page >= pageCount - 1}
              onClick={() => setRequestedPage(page + 1)}
            >
              Вперёд
            </JxButton>
          </span>
        </footer>
      ) : null}
    </section>
  );
}

